require __DIR__.'/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('POST only');}$roomId=require_room_id($_GET['room']??'');if(!is_room_host($roomId)||!csrf_matches($roomId,$_POST['csrf']??null)){http_response_code(403);exit('Host authorization required');}
